WITH thresholds AS (SELECT percentile_approx(CASE WHEN dur>0 THEN (sbytes+dbytes)/dur END,0.99) p99_bps FROM flows), high_rate_normal AS (SELECT srcip,'normal_flow_at_or_above_dataset_p99_bps' rule_name,COUNT(*) evidence_flows,MAX((sbytes+dbytes)/dur) max_bps FROM flows CROSS JOIN thresholds WHERE label=0 AND dur>0 AND (sbytes+dbytes)/dur>=p99_bps GROUP BY srcip), repeated_normal AS (SELECT srcip,'normal_source_with_100_or_more_flows' rule_name,COUNT(*) evidence_flows,CAST(NULL AS DOUBLE) max_bps FROM flows WHERE label=0 GROUP BY srcip HAVING COUNT(*)>=100)
SELECT * FROM (SELECT * FROM high_rate_normal UNION ALL SELECT * FROM repeated_normal) x ORDER BY evidence_flows DESC LIMIT {{TOP_N}}
